export const effectKinds={condition:'Condição',shield:'Escudo adicional',defense:'Bônus de Defesa',check:'Bônus de perícias/resistências',damage:'Bônus de dano'};
export function effectsState(c){const effects=c.effects??[];if(!Array.isArray(effects)||effects.length>30)throw Error('Limite de 30 efeitos por ficha.');const ids=new Set();for(const e of effects){if(!e||typeof e.id!=='string'||!e.id||ids.has(e.id)||typeof e.name!=='string'||!e.name.trim()||e.name.length>80||!Object.hasOwn(effectKinds,e.kind)||!Number.isInteger(e.amount)||!((e.kind==='condition'&&e.amount===0)||(e.kind==='shield'&&e.amount>=1&&e.amount<=9999)||(['defense','check','damage'].includes(e.kind)&&e.amount!==0&&Math.abs(e.amount)<=30))||!(e.rounds===null||Number.isInteger(e.rounds)&&e.rounds>=1&&e.rounds<=100)||!(e.remaining===null&&e.rounds===null||Number.isInteger(e.remaining)&&e.remaining>=1&&e.remaining<=e.rounds)||!(e.combatId===null||typeof e.combatId==='string'))throw Error('Efeito temporário inválido.');ids.add(e.id);}return effects;}
export function effectBonus(c,kind){return effectsState(c).filter(e=>e.kind===kind).reduce((sum,e)=>sum+e.amount,0);}
export function effectDescription(e){const value=e.kind==='condition'?'':e.kind==='shield'?' · '+e.amount+' de escudo':' · '+(e.amount>0?'+':'')+e.amount+' '+({defense:'Defesa',check:'testes',damage:'dano'}[e.kind]);return e.name+value+(e.remaining===null?' · até remover':' · '+e.remaining+' rodada(s)');}
export function effectsSummary(c){return effectsState(c).map(effectDescription).join('; ');}
export function withEffects(c,effects,clock=c.effectClock){const next={...c,effects};if(effects.length&&clock)next.effectClock={...clock};else delete next.effectClock;return next;}
export function addEffect(c,{id,name,kind,amount=0,rounds=2},clock){const effects=effectsState(c),effect={id,name:name.trim(),kind,amount:kind==='condition'?0:amount,rounds,remaining:rounds,combatId:rounds!==null&&clock.running?clock.id:null};const next=withEffects(c,[...effects,effect],clock);effectsState(next);return next;}
export function removeEffect(c,id){return withEffects(c,effectsState(c).filter(e=>e.id!==id));}
export function advanceEffects(c,clock){const old=c.effectClock,effects=effectsState(c);if(!effects.length)return c;const ended=Boolean(old?.running&&!clock.running);let changed=false;const next=[];for(const e of effects){if(e.rounds===null){next.push(e);continue;}if(ended||clock.running&&e.combatId&&e.combatId!==clock.id){changed=true;continue;}if(!clock.running){next.push(e);continue;}let remaining=e.remaining;if(e.combatId===clock.id&&old?.id===clock.id)remaining-=Math.max(0,clock.round-old.round);if(remaining<=0){changed=true;continue;}const updated={...e,remaining,combatId:clock.id};changed=changed||remaining!==e.remaining||e.combatId!==clock.id;next.push(updated);}if(!changed&&old?.id===clock.id&&old?.round===clock.round&&old?.running===clock.running)return c;return withEffects(c,next,clock);}
export function absorbEffectShields(c,amount){let rest=amount,absorbed=0;const effects=[];for(const e of effectsState(c)){if(e.kind!=='shield'||rest<=0){effects.push(e);continue;}const taken=Math.min(rest,e.amount);rest-=taken;absorbed+=taken;if(taken<e.amount)effects.push({...e,amount:e.amount-taken});}return {character:withEffects(c,effects),absorbed,remainingDamage:rest};}
